// Symptom: the Operations and Radar locked card lay out side by side (row) instead of stacked.
// Check each page's card regions: no two top-level cards may share a row.
const paths = ['/ops/operations', '/ops/radar'];
for (const path of paths) {
  await page.goto(path);
  await expect(page.getByRole('heading', { name: /operations|locked/i }).first()).toBeVisible();
  const sharesRow = await page.evaluate(() => {
    const cards = [...document.querySelectorAll('main section, main article, main [role="region"]')]
      .filter(el => el.offsetParent !== null && el.getBoundingClientRect().height > 0)
      .filter(el => !el.parentElement.closest('section, article, [role="region"]'));
    for (let i = 0; i < cards.length; i++) {
      for (let j = i + 1; j < cards.length; j++) {
        const a = cards[i].getBoundingClientRect();
        const b = cards[j].getBoundingClientRect();
        const overlapY = Math.min(a.bottom, b.bottom) - Math.max(a.top, b.top);
        if (overlapY > 0 && Math.abs(a.top - b.top) < 4) return true;
      }
    }
    return false;
  });
  if (sharesRow) throw new Error(`Cards on ${path} lay out in a row`);
}
